                    <p class="text-xs text-slate-500 mt-1">Linear scan required regardless of order.</p>
                </div>
                <div class="glass-panel p-4 rounded-xl border-l-4 border-rose-500">
                    <h3 class="text-slate-400 text-xs uppercase font-bold mb-1">Worst Case</h3>
                    <p class="text-white font-semibold">O(n)</p>
                    <p class="text-xs text-slate-500 mt-1">The largest element is the last one.</p>
                </div>
            </div>

        </div>
    </main>

    <script>
        // --- Application State ---
        const state = {
            array: [],
            isAnimating: false,
