                    </button>

                    <button onclick="app.triggerScenario('null')" class="group relative px-4 py-3 rounded-lg bg-slate-800 hover:bg-slate-700 border border-slate-600 hover:border-yellow-500 transition-all duration-200 text-left">
                        <div class="flex items-center justify-between mb-1">
                            <span class="font-semibold text-slate-200 group-hover:text-yellow-400">Null Input</span>
