                </div>
            </div>

            <!-- Code Viewer -->
            <div class="flex-1 overflow-y-auto p-6 relative bg-[#282c34]">
                <div class="absolute top-2 right-4 text-xs text-slate-500 font-mono">UserRegistration.java</div>
